{"language":"js","summary":"Survey repo layout, git state, and memory before sizing the audit","code":"const sh = async (c)=> (await Bun.$`sh -c ${c}`.nothrow().text());
const [pwd, tree, git, langs, mem] = await parallel([
  ()=>sh('pwd; ls -la'),
  ()=>sh('git ls-files 2>/dev/null | head -400 | wc -l; git ls-files 2>/dev/null | sed "s|/[^/]*$||" | sort | uniq -c | sort -rn | head -40'),
  ()=>sh('git log --oneline -5 2>&1; git status --short 2>&1 | head'),
  ()=>sh('git ls-files 2>/dev/null | sed "s/.*\\.//" | sort | uniq -c | sort -rn | head -15'),
  ()=>sh('ls ~/.omo 2>/dev/null; ls .omo 2>/dev/null; echo; ls $(git rev-parse --show-toplevel 2>/dev/null) | head -50'),
]);
print(pwd,'\n---\n',tree,'\n---\n',git,'\n---\n',langs,'\n---\n',mem);"}

